begin;
select no_plan();
select ok(not has_function_privilege('anon','api.execute_onboarding_publish_server(uuid,text,jsonb)','execute'),'Anonymous cannot choose subject');
select ok(not has_function_privilege('authenticated','api.execute_onboarding_publish_server(uuid,text,jsonb)','execute'),'Browser cannot choose subject');
select ok(has_function_privilege('service_role','api.execute_onboarding_publish_server(uuid,text,jsonb)','execute'),'Only fixed server admission');
select ok(not has_function_privilege('service_role','api.publish_current_onboarding(uuid,text,text)','execute'),'Original bundle RPC stays closed');
select ok(not has_table_privilege('service_role','core.identity_publications','SELECT,INSERT,UPDATE,DELETE'),'Raw publication stays private');
set local role anon;
select throws_ok($$select api.execute_onboarding_publish_server(null,null,'{}')$$,'42501',null,'Actual anonymous denied');
reset role;
set local role authenticated;
select throws_ok($$select api.execute_onboarding_publish_server(null,null,'{}')$$,'42501',null,'Actual browser denied');
reset role;
insert into auth.users(id,email) values('27800000-0000-4000-8000-000000000001','publish278-one@example.test'),('27800000-0000-4000-8000-000000000002','publish278-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('27800000-0000-4000-8000-000000000001','27800000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal',revision=6 where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'publish278-'||right(auth_user_id::text,6),owner_id,'current' from actors;
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Reviewed Identity','Private review',1 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
set local request.jwt.claims='{"role":"authenticated","sub":"27800000-0000-4000-8000-000000000001"}';
select is(api.save_current_owner_product_draft('https://example.test/private-product','Private Product',null)->>'status','success','Save private Product');
select is(api.save_current_owner_resource_draft('menu',null,'Private Resource',null)->>'status','success','Save incomplete private Resource');
create temporary table review as select api.confirm_current_onboarding_preview(api.resolve_current_onboarding_preview()->>'snapshot_hash') as receipt;
create temporary table acknowledgment(result jsonb);
grant select on review to service_role;
grant select,insert on acknowledgment to service_role;
create function pg_temp.publish_identity(subject uuid,receipt jsonb) returns jsonb language sql as $$
 select api.execute_onboarding_publish_server(subject,'publish_current_onboarding_identity',jsonb_build_object('input_receipt_id',receipt->>'receipt_id','input_snapshot_hash',receipt->>'snapshot_hash'));
$$;
grant execute on function pg_temp.publish_identity(uuid,jsonb) to service_role;
set local request.jwt.claims='{"role":"service_role","sub":"27800000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='27800000-0000-4000-8000-000000000002';
set local role service_role;
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000002',(select receipt from review))->>'status','review_required','Foreign receipt cannot publish another Owner');
select is(api.execute_onboarding_publish_server('27800000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','Bundle RPC not selectable');
select is(api.execute_onboarding_publish_server('27800000-0000-4000-8000-000000000001','publish_current_onboarding_identity',(select jsonb_build_object('input_receipt_id',receipt->>'receipt_id','input_snapshot_hash',receipt->>'snapshot_hash','input_bundle','resource') from review))->>'status','unavailable','Caller cannot select Item bundle');
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000099',(select receipt from review))->>'status','owner_missing','Unknown subject cannot borrow ambient Owner');
insert into acknowledgment select pg_temp.publish_identity('27800000-0000-4000-8000-000000000001',(select receipt from review));
select is((select result->>'status' from acknowledgment),'success','Explicit fixed Identity-only publication succeeds');
select is((select result->>'bundle' from acknowledgment),'identity_only','Literal fixed bundle');
select is((select result->'item_status' from acknowledgment),'null'::jsonb,'No Item publication claim');
select is(current_setting('request.jwt.claim.sub'),'27800000-0000-4000-8000-000000000002','Subject restored');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"27800000-0000-4000-8000-000000000002"}'::jsonb,'Whole claims restored');
reset role;
select is((select count(*)::int from core.identity_publications where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000001')),1,'Exactly one own publication');
select is((select count(*)::int from core.identity_publications where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000002')),0,'Foreign Owner unchanged');
select is((select count(*)::int from core.spill_item_publications where owner_id in(select owner_id from actors)),0,'All Items remain private');
select is((select count(*)::int from core.product_drafts where owner_id in(select owner_id from actors)),1,'Product retained');
select is((select count(*)::int from core.resource_drafts where owner_id in(select owner_id from actors)),1,'Resource retained');
select is((select revision from core.owner_onboarding_progress where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000001')),7::bigint,'Only progress advances');
select is((select revision from core.identity_working where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000001')),1::bigint,'Working revision unchanged');
set local role service_role;
select is(api.execute_public_identity_server('read','publish278-000001',null)->>'display_name','Reviewed Identity','Actual public reader consumes published snapshot');
reset role;
update core.identity_working set display_name='New private Working',revision=2 where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000001');
set local role service_role;
select is(api.execute_public_identity_server('read','publish278-000001',null)->>'display_name','Reviewed Identity','Working edit does not change public read');
reset role;
update core.onboarding_preview_receipts set issued_at=now()-interval '70 minutes',expires_at=now()-interval '1 hour' where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000001');
insert into core.identity_profile_text_working(owner_id,display_name,bio,revision,source_profile_revision) select owner_id,'New private overlay',null,1,1 from actors;
set local role service_role;
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000001',(select receipt from review)),(select result from acknowledgment),'Exact receipt replay survives expiry and new Working overlay');
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000001',(select receipt||'{"receipt_id":"27800000-0000-4000-8000-000000000009"}' from review))->>'status','conflicting_intent','Changed intent cannot republish');
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000002',(select receipt from review))->>'status','identity_preparation_pending','Legacy snapshot cannot omit recoverable Profile Text');
reset role;
delete from core.identity_profile_text_working where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000002');
insert into core.identity_block_collections_working(owner_id) select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000002';
set local role service_role;
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000002',(select receipt from review))->>'status','identity_preparation_pending','Modular collection cannot be silently omitted');
reset role;
update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000001');
set local role service_role;
select is(pg_temp.publish_identity('27800000-0000-4000-8000-000000000001',(select receipt from review))->>'status','owner_not_eligible','Current restriction wins over successful replay');
reset role;
-- Forced transaction failure in this rolled-back fixture must restore admission
-- settings and cannot leave an acknowledgment or complete onboarding.
delete from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000002');
set local request.jwt.claims='{"role":"authenticated","sub":"27800000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='27800000-0000-4000-8000-000000000002';
create temporary table failed_review as select api.confirm_current_onboarding_preview(api.resolve_current_onboarding_preview()->>'snapshot_hash') as receipt;
grant select on failed_review to service_role;
create function pg_temp.reject_publication_fixture() returns trigger language plpgsql as $$ begin raise exception 'isolated publication failure'; end; $$;
create trigger reject_publication_fixture before insert on core.identity_publications for each row execute function pg_temp.reject_publication_fixture();
set local request.jwt.claims='{"role":"service_role","sub":"27800000-0000-4000-8000-000000000099"}';
set local request.jwt.claim.sub='27800000-0000-4000-8000-000000000099';
set local role service_role;
select throws_ok($$select pg_temp.publish_identity('27800000-0000-4000-8000-000000000002',(select receipt from failed_review))$$,'P0001','isolated publication failure','Transaction exception propagates without fabricated acknowledgment');
select is(current_setting('request.jwt.claim.sub'),'27800000-0000-4000-8000-000000000099','Exception restores subject');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"27800000-0000-4000-8000-000000000099"}'::jsonb,'Exception restores whole claims');
reset role;
select ok((select onboarding_completed_at is null from core.owners where id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000002')),'Exception cannot complete onboarding');
select is((select count(*)::int from core.first_onboarding_publications where owner_id=(select owner_id from actors where auth_user_id='27800000-0000-4000-8000-000000000002')),0,'Exception leaves no success record');
select * from finish();
rollback;
